      joistSpanFt: '', joistSpanIn: '0', joistMaterial: '2x8',
      postHeightFt: '3', postHeightIn: '0', postSize: '6x6',
      fasciaMaterial: '2x12', ledgerCount: '1', postCountPerBeam: '',
      overrideBeamLen: false, overrideJoistSpan: false, 
