      data.roomWidV1 = roomWidV1; data.roomWidV2 = roomWidV2; data.roomWidV3 = roomWidV3; data.roomWidV4 = roomWidV4;
      data.tileLenV1 = tileLenV1; data.tileLenV2 = tileLenV2; data.tileLenV3 = tileLenV3; data.tileLenV4 = tileLenV4;
