                    <input inputMode="decimal" type="number" value={angle} onChange={(e) => setAngle(e.target.value)} placeholder="90" 
                      className={`w-full border rounded-xl p-3 text-center font-black text-lg outline-none transition-colors shadow-inner ${theme !== 'light' ? 'bg-[#111] border-accent/50 text-white focus:border-accent' : 'bg-white border-accent/50 text-black focus:border-accent'}`} 
                    />
