                  // START HEIGHT (B)
                  const ftB = parseFloat(b1) || 0;
                  const inB = parseFloat(b2) || 0;
                  const fracB = parseFloat(b4) ? (parseFloat(b3) || 0) / parseFloat(b4) : 0;
                  const valB = ftB + (inB + fracB) / subDivisor;
                  const displayStart = valB > 0 
