                        <polygon points={isShort ? "102,50 106,46 106,106 102,110" : "102,70 106,66 106,106 102,110"} fill={theme === 'dark' ? '#444' : '#bbb'} stroke={theme === 'dark' ? '#333' : '#aaa'} strokeWidth="0.5" />

