                        {/* Input Pill Component (Overlapping Left Panel) */}
                        <motion.g initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ duration: 0.4 }}>
                          <rect x="0" y="45" width="70" height="30" rx="15" fill={theme === "dark" ? "#0a0a0a" : "#fff"} stroke={accentColor} strokeWidth="2" />
                          <text paintOrder="stroke fill" strokeWidth="3" stroke={theme !== 'light' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.8)'}  letterSpacing="-0.5px" x="35" y="62" fill={theme === "dark" ? "#fff" : "#000"} fontSize="9" fontWeight="black" textAnchor="middle">
                            {formattedInput}
                          </text>
                          <text paintOrder="stroke fill" strokeWidth="3" stroke={theme !== 'light' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.8)'} fontFamily="monospace" letterSpacing="-0.5px" x="35" y="85" style={{ fill: accentColor }} fontSize="5" fontWeight="bold" textAnchor="middle" className="uppercase tracking-widest">
                            INPUT
                          </text>
                        </motion.g>

                        {/* Output Display Panel (Overlapping Right Panel) */}
                        <motion.g initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ duration: 0.4, delay: 0.1 }}>
                          <rect x="200" y="40" width="80" height="40" rx="4" fill={theme === "dark" ? "#0a0a0a" : "#fff"} style={{ stroke: hasInput ? secondaryColor : (theme === "dark" ? "#444" : "#ccc") }} strokeWidth="2" />
                          
                          {hasInput ? (
                            <g>
                              <text paintOrder="stroke fill" strokeWidth="3" stroke={theme !== 'light' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.8)'}  letterSpacing="-0.5px" x="240" y="62" style={{ fill: secondaryColor }} fontSize="9" fontWeight="black" textAnchor="middle">
                                {finalResultStr.length > 10 ? finalResultStr.slice(0, 10) + '..' : finalResultStr}
                              </text>
                              <text paintOrder="stroke fill" strokeWidth="3" stroke={theme !== 'light' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.8)'} fontFamily="monospace" letterSpacing="-0.5px" x="240" y="85" style={{ fill: secondaryColor }} fontSize="5" fontWeight="bold" textAnchor="middle" className="uppercase tracking-widest">
                                CONVERTED
                              </text>
                            </g>
                          ) : (
                            <g>
                              <rect x="238" y="55" width="4" height="4" fill={theme === "dark" ? "#444" : "#ccc"} />
                              <text paintOrder="stroke fill" strokeWidth="3" stroke={theme !== 'light' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.8)'}  letterSpacing="-0.5px" x="240" y="85" fill={theme === "dark" ? "#555" : "#aaa"} fontSize="5" fontWeight="bold" textAnchor="middle" className="uppercase tracking-widest">
                                STANDBY
                              </text>
                            </g>
                          )}
                        </motion.g>
                        
                        {/* Pulsating Micro-Lights */}
                        <circle cx="28" cy="42" r="1.5" fill={hasInput ? "#00FF41" : "#333"} />
