                                <text paintOrder="stroke fill" strokeWidth="3" stroke={theme !== 'light' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.8)'}  letterSpacing="-0.5px" x="155" y="46.5" style={{ fill: secondaryColor }} fontSize="5" fontWeight="black">Mortar Joint</text>
                                
